const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true">${ICONS[name]||ICONS.book}</svg>`;
const validSavedEntries=()=>Object.entries(saved).filter(([r,v])=>parseReference(r)&&v&&typeof v.text==='string');
function notify(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3400);}
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{notify('Your browser could not save this. Check its storage settings.');return false;}}
function updateSavedUI(){ $('#saved-count').textContent=validSavedEntries().length;document.querySelectorAll('[data-action="save"]').forEach(b=>{let on=!!saved[b.dataset.ref];b.classList.toggle('is-saved',on);b.setAttribute('aria-pressed',String(on));b.setAttribute('aria-label',`${on?'Unsave':'Save'} ${b.dataset.ref}`);if(b.querySelector('.save-label'))b.querySelector('.save-label').textContent=on?'Saved':'Save';});}
function parseReference(value){const normalized=String(value).trim().replace(/^psalms\b/i,'Psalm');const m=normalized.match(/^(.+?)\s+(\d{1,3})(?::(\d{1,3}))?$/);if(!m)return null;const book=DATA.index.find(b=>b.name.toLowerCase()===m[1].toLowerCase());if(!book||+m[2]<1||+m[2]>book.chapters||m[3]&&+m[3]<1)return null;return {book,ch:+m[2],verse:m[3]?+m[3]:null};}
function refURL(ref){const p=parseReference(ref);return p?`#/read/${p.book.id}/${p.ch}${p.verse?'/'+p.verse:''}`:'#/read/19/23';}
function searchTopics(query){const q=query.toLowerCase().replace(/[^a-z0-9 ]/g,' ');const words=q.split(/\s+/).filter(w=>w.length>2);return DATA.topics.map(t=>({t,score:t.tags.reduce((n,tag)=>n+(words.includes(tag)?2:q.includes(tag)&&tag.length>4?1:0),0)+(t.title.toLowerCase().includes(q.trim())&&q.trim()?3:0)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).map(x=>x.t);}
function scene(palette=0,variant='wide'){
 const pal=[['#e3e7cd','#c2d5bf','#a6bd9b','#718e6d','#395c48','#244b3d'],['#efdfba','#d9d6ab','#bdc494','#8a9a6c','#62774f','#3a5a41'],['#b8c7c4','#8aaba5','#70938c','#4d706c','#345951','#203d38'],['#efe1c0','#dbd3a6','#b5bd86','#889b69','#58764f','#32573f']][palette%4];
 let trees='';for(let i=0;i<12;i++){const x=455+i*22,y=222+Math.sin(i*.8)*18,s=10+(i%4)*3;trees+=`<path d="M${x} ${y+18}v${-s*2}" stroke="${pal[5]}" stroke-width="2"/><ellipse cx="${x}" cy="${y-5}" rx="${s*.6}" ry="${s}" fill="${pal[4]}"/>`;}
 return `<svg class="landscape" viewBox="0 0 800 420" preserveAspectRatio="xMidYMid slice" role="img" aria-label="An artistic landscape of hills, a winding path, and quiet water inspired by Psalm 23"><defs><linearGradient id="sky-${variant}-${palette}" x2="0" y2="1"><stop stop-color="${pal[0]}"/><stop offset="1" stop-color="${pal[1]}"/></linearGradient><linearGradient id="ground-${variant}-${palette}" x2="0" y2="1"><stop stop-color="${pal[4]}"/><stop offset="1" stop-color="${pal[5]}"/></linearGradient></defs><rect width="800" height="420" fill="url(#sky-${variant}-${palette})"/><circle cx="550" cy="95" r="48" fill="#fff2bf" opacity=".6"/><circle cx="550" cy="95" r="63" fill="#fff4ca" opacity=".12"/><path d="M-30 224Q100 127 204 167T420 155T680 126T850 175V420H-30Z" fill="${pal[1]}"/><path d="M-20 224Q130 165 230 213T440 203T660 169T830 205V420H-20Z" fill="${pal[2]}"/><path d="M-20 303Q102 165 284 248T570 208T830 249V420H-20Z" fill="${pal[3]}"/>${trees}<path d="M-20 270Q110 218 235 291T490 280T820 283V420H-20Z" fill="${pal[4]}"/><path d="M-20 341Q115 285 240 345T490 329T820 355V420H-20Z" fill="url(#ground-${variant}-${palette})"/><path d="M338 236c48 14 78 18 57 39s-101 24-91 43 124 26 95 56-119 28-132 62h78c12-30 112-33 103-64s-124-40-108-59 89-25 87-42-48-24-89-35" fill="#e4d5a4" opacity=".75"/><path d="M702 252c-36 19-98 36-84 56s106 22 88 48-93 30-143 64h173c11-21 46-47 14-68s-99-31-108-46 36-33 60-54Z" fill="#b0cab7" opacity=".65"/><path d="m647 327 42 2m-7 46 31 1m-88 20 38 1" stroke="#e8ebca" stroke-width="2" opacity=".4"/><path d="M72 363V261m0 68-21-20m21-4 25-24" stroke="${pal[5]}" stroke-width="5"/><ellipse cx="67" cy="268" rx="34" ry="47" fill="${pal[5]}"/><ellipse cx="88" cy="280" rx="27" ry="35" fill="${pal[5]}"/><g fill="#e3ddb3" opacity=".5"><circle cx="148" cy="350" r="1.5"/><circle cx="163" cy="357" r="1"/><circle cx="550" cy="380" r="1.4"/><circle cx="532" cy="386" r="1.1"/><circle cx="185" cy="382" r="1.5"/></g><path d="M168 92q6-7 12 0 6-7 12 0m33 24q4-5 8 0 4-5 8 0" stroke="${pal[4]}" opacity=".5" stroke-width="1.4" fill="none"/></svg>`;
}
const topicCard=t=>`<a class="topic-card" href="#/help/${t.id}"><span class="topic-icon">${icon(t.icon)}</span><span class="arrow" aria-hidden="true">↗</span><h3>${t.title}</h3><p>${t.subtitle}</p></a>`;
const personCard=p=>`<a class="person-card" href="#/people/${p.id}"><span class="person-symbol">${icon(p.icon)}</span><h3>${p.name}</h3><p>${p.tag}</p><span class="more">Explore the story <span aria-hidden="true">↗</span></span></a>`;
const searchForm=(value='')=>`<form class="search-box" data-form="search" role="search">${icon('search')}<label for="help-search" class="visually-hidden">Search a feeling, word or Bible reference</label><input id="help-search" name="query" type="search" maxlength="150" placeholder="A feeling, a word, or a Bible reference…" value="${escapeHTML(value)}" required><button aria-label="Search Scripture and topics">${icon('arrow')}</button></form>`;
const saveButton=(ref,withLabel=false)=>`<button class="icon-btn ${saved[ref]?'is-saved':''}" data-action="save" data-ref="${escapeHTML(ref)}" aria-label="${saved[ref]?'Unsave':'Save'} ${escapeHTML(ref)}" aria-pressed="${!!saved[ref]}">${icon('bookmark')}${withLabel?`<span class="save-label">${saved[ref]?'Saved':'Save'}</span>`:''}</button>`;
function studyLink(ref){return window.SFL_VERSE_STUDIES.link(ref)||(ref.startsWith('Psalm 23:')?`#/study/23/${ref.split(':')[1]}`:window.SFL_PSALM46.link(ref)||(ref.startsWith('Psalm ')?'#/psalms/'+ref.split(' ')[1].replace(':','/'):''));}
const HERO_VERSES=[["He leads me beside quiet waters.","PSALM 23:2"],["The LORD is my shepherd; I shall not want.","PSALM 23:1"],["Be still and know that I am God","PSALM 46:10"],["Do not fear, for I am with you; do not be afraid, for I am your God.","ISAIAH 41:10"],["They are new every morning; great is Your faithfulness!","LAMENTATIONS 3:23"],["My help comes from the LORD, the Maker of heaven and earth.","PSALM 121:2"],["Do not be afraid; do not be discouraged, for the LORD your God is with you wherever you go.","JOSHUA 1:9"],["Come to Me, all you who are weary and burdened, and I will give you rest.","MATTHEW 11:28"],["This is the day that the LORD has made; we will rejoice and be glad in it.","PSALM 118:24"],["But those who wait upon the LORD will renew their strength","ISAIAH 40:31"],["When I am afraid, I put my trust in You.","PSALM 56:3"],["Peace I leave with you; My peace I give to you.","JOHN 14:27"]];
function dailyVersePool(){const lists=DATA.topics.map(t=>t.refs.filter(r=>DATA.verses[r]&&DATA.verses[r].length<=150)),pool=[],seen=new Set();for(let k=0;lists.some(l=>k<l.length);k++)lists.forEach(l=>{const r=l[k];if(r&&!seen.has(r)){seen.add(r);pool.push(r);}});return pool;}
function heroVerse(date=new Date()){const day=Math.floor(Date.UTC(date.getFullYear(),date.getMonth(),date.getDate())/86400000),pool=dailyVersePool();if(pool.length){const ref=pool[((day%pool.length)+pool.length)%pool.length];return{text:DATA.verses[ref],ref};}const v=HERO_VERSES[((day%HERO_VERSES.length)+HERO_VERSES.length)%HERO_VERSES.length];return{text:v[0],ref:v[1]};}
const PLACE_KEY='scripture-for-life.last-place',DONE_KEY='scripture-for-life.episodes-done';
function timeAgo(ts){const m=Math.round((Date.now()-ts)/60000);if(!(m>=0))return '';if(m<1)return 'just now';if(m<60)return `${m} min ago`;const h=Math.round(m/60);if(h<24)return `${h} hour${h===1?'':'s'} ago`;const d=Math.round(h/24);return d===1?'yesterday':`${d} days ago`;}
function lastPlace(){const p=safeJSON(PLACE_KEY,{});if(!p||typeof p!=='object')return null;return [p.story,p.psalm].filter(x=>x&&typeof x.href==='string'&&/^#\/[a-z0-9]+\//.test(x.href)&&Number.isFinite(x.ts)).sort((a,b)=>b.ts-a.ts)[0]||null;}
function recordPlace(kind,entry){const p=safeJSON(PLACE_KEY,{});const next=p&&typeof p==='object'&&!Array.isArray(p)?p:{};next[kind]={...entry,ts:Date.now()};try{localStorage.setItem(PLACE_KEY,JSON.stringify(next));}catch{}}
function continueCard(){const p=lastPlace();if(!p)return '';const title=escapeHTML(p.title||p.label||'Continue reading');return `<a class="topic-card continue-card" href="${escapeHTML(p.href)}"><span class="topic-icon">${icon(p.kind==='psalm'?'leaf':'book')}</span><span class="arrow" aria-hidden="true">↗</span><span class="eyebrow">Continue where you left off</span><h3>${title}</h3><p>${escapeHTML(p.label||'')}${p.ts?` · ${escapeHTML(timeAgo(p.ts))}`:''}</p></a>`;}
function episodesDone(){const d=safeJSON(DONE_KEY,{});return d&&typeof d==='object'&&!Array.isArray(d)?d:{};}
function trackPlace(parts){const main=$('#main');if(!main||main.querySelector('.empty'))return;
 if(parts.length===3&&/^\d+$/.test(parts[1])&&/^\d+$/.test(parts[2])&&main.querySelector('.gen-narrative')){const m=(main.querySelector('.gen-toolbar span')?.textContent||'').match(/SCENE\s+(\d+)\s+OF\s+(\d+)/i);if(!m)return;const slug=parts[0]==='stories'?'genesis':parts[0],n=+m[1],total=+m[2],book=storyBookName(slug),title=main.querySelector('.gen-content h1')?.textContent.trim()||'';recordPlace('story',{kind:'story',href:`#/${parts[0]}/${parts[1]}/${n}`,title,label:`${book} · Episode ${parts[1]} · Scene ${n} of ${total}`});if(n===total){const d=episodesDone();const list=Array.isArray(d[slug])?d[slug]:[];if(!list.includes(parts[1])){d[slug]=[...list,parts[1]];try{localStorage.setItem(DONE_KEY,JSON.stringify(d));}catch{}}}return;}
 let psalm=0,verse=0,href='';
 if(parts[0]==='study'&&parts[1]==='46'){const sec=+(parts[2]||1);const r=window.SFL_PSALM46?.refs?.(sec)?.[0];psalm=46;verse=r?+String(r).split(':')[1]:0;href=`#/study/46/${sec}`;}
 else if(parts[0]==='study'){psalm=+parts[1];verse=+(parts[2]||(main.querySelector('[data-current-verse]')?.dataset.currentVerse)||1);href=`#/study/${psalm}/${verse}`;}
 else if(parts[0]==='psalms'&&parts[1]){psalm=+parts[1];verse=+(parts[2]||0);href=`#/psalms/${psalm}${verse?'/'+verse:''}`;}
 if(!Number.isInteger(psalm)||psalm<1||psalm>150||!Number.isInteger(verse)||verse<0)return;const label=verse?`Psalm ${psalm}:${verse}`:`Psalm ${psalm}`;recordPlace('psalm',{kind:'psalm',href,title:label,label:'Psalms · BSB'});}
function markDoneTiles(){const tiles=document.querySelectorAll('#main .gen-episode-tile');if(!tiles.length)return;const done=episodesDone();tiles.forEach(t=>{const m=(t.getAttribute('href')||'').match(/^#\/([a-z0-9]+)\/(\d+)\//);if(!m)return;const slug=m[1]==='stories'?'genesis':m[1],id=m[2],kicker=t.querySelector('.gen-kicker');const len=+((kicker?.textContent||'').match(/(\d+)\s+SCENES/i)||[])[1];const prog=safeJSON(`scripture-for-life.${slug}-progress`,{});const finished=(Array.isArray(done[slug])&&done[slug].includes(id))||(len&&prog&&+prog[id]===len);if(finished&&kicker&&!kicker.querySelector('.episode-done'))kicker.insertAdjacentHTML('beforeend',' <span class="episode-done" role="img" aria-label="Episode completed">✓</span>');});}
function home(){return `<div class="container"><section class="hero"><div><span class="eyebrow">A little light for your everyday life</span><h1>Find help in<br><em>God’s Word.</em></h1><p class="intro">Whatever you’re carrying today, start here. Find Scripture for your needs, understand its meaning, and discover the stories behind it.</p>${searchForm()}<p class="search-hint">Try “I feel afraid,” “shepherd,” or “John 3:16”</p><p class="gen-home-quick"><a href="#/books">Browse all stories →</a><span aria-hidden="true"> · </span><a href="#/journey">The Bible Journey →</a></p>${continueCard()}</div><div class="hero-art">${scene(0,'home')}<span class="art-credit">AN ILLUSTRATION INSPIRED BY PSALM 23</span>${(()=>{const v=heroVerse(),ok=!!DATA.verses[v.ref];return ok?`<button type="button" class="art-caption daily-verse" data-action="open-verse" data-ref="${escapeHTML(v.ref)}" aria-label="Verse of the day, ${escapeHTML(v.ref)}. Open to save, copy, listen or reflect">“${escapeHTML(v.text)}”<small>${escapeHTML(v.ref.toUpperCase())} · BSB · TAP TO REFLECT</small></button>`:`<div class="art-caption">“${escapeHTML(v.text)}”<small>${escapeHTML(v.ref)} · BSB · EXCERPT</small></div>`;})()}</div></section><section class="help-section" aria-labelledby="help-title"><div class="section-heading"><div><h2 id="help-title">What are you facing today?</h2><p>You don’t have to find the perfect words.</p></div></div><div class="topic-grid">${DATA.topics.map(topicCard).join('')}</div></section></div>`;}
function verseCard(ref){return `<article class="verse-card"><div class="verse-heading"><span class="verse-ref">${escapeHTML(ref)}<span class="translation">BSB</span></span>${saveButton(ref)}</div><p class="verse-text" data-speakref="${escapeHTML(ref)}">${escapeHTML(textFor(ref))}</p><div class="verse-actions"><a class="text-link" href="${refURL(ref)}">Read in context</a>${studyLink(ref)?`<a class="text-link" href="${studyLink(ref)}">Understand this verse</a>`:''}<button class="icon-btn" data-action="listen-verse" data-ref="${escapeHTML(ref)}">${icon('volume')} Listen</button><button class="icon-btn" data-action="open-verse" data-ref="${escapeHTML(ref)}">${icon('book')} Reflect</button></div></article>`;}
function pickTopicRefs(refs,n=10){if(window.SFL_TOPIC_SHOW_ALL)return refs;const a=refs.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a.slice(0,n);}
function helpPage(id){const t=DATA.topics.find(t=>t.id===id);if(!t)return notFound();return `<div class="container"><header class="page-head"><a class="back" href="#/">${icon('back')} Find help</a><span class="eyebrow">Scripture for what you’re facing</span><h1>${t.title}</h1><p>${t.subtitle} Take your time with the passages below.</p></header><div class="topic-layout topic-layout-single"><section aria-label="Passages about ${t.title}">${pickTopicRefs(t.refs).map(verseCard).join('')}</section></div></div>`;}
function studyPage(n){n=Math.max(1,Math.min(6,Number(n)||1));const s=STUDIES[n-1],ref=`Psalm 23:${n}`;return `<div class="container phone-verse-first">${window.SFL_PSALMS.switcher(23)}<header class="study-top"><div><span class="eyebrow">Psalm 23 · Poetry & imagery</span><h1>The LORD is my shepherd.</h1><p>Read the poem verse by verse, with illustrations of its care, rest, and hope.</p><button class="btn outline" data-action="listen-psalm">${icon('volume')} Listen to all of Psalm 23</button></div><div class="study-landscape psalm23-landscape">${window.SFL_PSALM_ART.render(n)}<span class="scene-label">ILLUSTRATION INSPIRED BY THE PSALM · NOT A HISTORICAL LOCATION</span></div></header>${window.SFL_PSALM_ART.verseNav(n)}<div class="study-body"><section class="study-verse"><span class="eyebrow">Psalm 23:${n} · BSB</span><h2>${s.title}</h2><p class="verse-text" data-speakref="${ref}">${escapeHTML(DATA.verses[ref])}</p><div class="verse-actions">${saveButton(ref,true)}<button class="icon-btn" data-action="listen-verse" data-ref="${ref}">${icon('volume')} Listen</button><button class="icon-btn" data-action="copy-verse" data-ref="${ref}">${icon('copy')} Copy verse</button></div><div class="study-bottom">${n>1?`<a class="btn outline" href="#/study/23/${n-1}">${icon('back')} Previous</a>`:`<a class="text-link" href="#/read/19/23">Read full chapter</a>`}<span>${n} of 6</span>${n<6?`<a class="btn" href="#/study/23/${n+1}">Next ${icon('arrow')}</a>`:`<a class="btn" href="#/saved">My reflections ${icon('bookmark')}</a>`}</div></section><section class="study-explainer" aria-label="Understand this verse"><div class="tabs" role="tablist" aria-label="Study tools">${[['meaning','Meaning'],['context','Context'],['explore','Explore'],['reflect','Reflect']].map(([key,label])=>`<button class="tab" role="tab" id="tab-${key}" aria-selected="${studyTab===key}" aria-controls="study-panel" tabindex="${studyTab===key?0:-1}" data-action="study-tab" data-tab="${key}">${label}</button>`).join('')}</div><div id="study-panel" class="tab-panel" role="tabpanel" tabindex="0" aria-labelledby="tab-${studyTab}">${studyPanel(n)}</div></section></div><section class="study-context"><div><h3>Meet David beyond this psalm.</h3><p>Follow the biblical account through courage, serious failure, and repentance. The precise circumstances behind Psalm 23 are not stated in the text.</p><a class="text-link" href="#/people/david">Explore David’s story ↗</a></div><div><h3>Grounded in the passage.</h3><p>Scripture is quoted from the public-domain BSB. These study notes are original editorial explanations, separate from the Bible text.</p><a class="source-link small" href="https://biblehub.com/bsb/psalms/23.htm" target="_blank" rel="noopener noreferrer">View Psalm 23 and its BSB translation footnotes ↗</a></div></section>${window.SFL_CONNECTIONS.related({ref})}${window.SFL_PSALMS.nextStudy(23)}</div>`;}
function studyPanel(n){const s=STUDIES[n-1],ref=`Psalm 23:${n}`;if(studyTab==='context')return `<span class="label">Literary context & translation notes</span><h3>See the wider picture.</h3><p>${s.context}</p><a class="text-link" href="#/read/19/23/${n}">Read the complete psalm ↗</a>`;if(studyTab==='explore')return `<span class="label">Explore the imagery</span><h3>Look a little closer.</h3>${s.explore.map(([term,body],i)=>`<details class="word-detail" ${i===0?'open':''}><summary>${term}</summary><p>${body}</p></details>`).join('')}<p class="sources-inline">Based on Psalm 23 and its <a class="source-link" href="https://biblehub.com/bsb/psalms/23.htm" target="_blank" rel="noopener noreferrer">BSB footnotes</a>. Images are literary; illustrations are artistic.</p>`;if(studyTab==='reflect')return `<span class="label">Personal application · take a quiet moment</span><p class="reflection-q">${s.reflect}</p>${noteField(ref)}<button class="btn outline" style="margin-top:12px" data-action="save-note" data-ref="${ref}">Save reflection ${icon('bookmark')}</button>`;return `<span class="label">An explanation · separate from Scripture</span><h3>${s.heading}</h3><p>${s.explain}</p><span class="label" style="margin-top:22px">Read alongside</span><div class="related-links">${s.related.map(r=>`<a class="ref-chip" href="${refURL(r)}">${r} ↗</a>`).join('')}</div>`;}
function noteField(ref){return `<label class="note-label" for="reflection-note">Your reflection or prayer</label><textarea id="reflection-note" class="note-input" data-note-ref="${escapeHTML(ref)}" maxlength="10000" placeholder="A thought, a question, or a prayer…"></textarea><p class="note-status">Saved only in this browser on this device. Anyone using this browser may see it.</p>`;}
function hydrateNotes(){document.querySelectorAll('[data-note-ref]').forEach(el=>{el.value=typeof notes[el.dataset.noteRef]==='string'?notes[el.dataset.noteRef]:'';});}
let sharedBiblePromise=null;async function loadBook(id){if(bookCache.has(id))return bookCache.get(id);if(!sharedBiblePromise)sharedBiblePromise=fetch('data/bible.json').then(r=>{if(!r.ok)throw Error('Bible text unavailable');return r.json();}).catch(e=>{sharedBiblePromise=null;throw e;});const full=await sharedBiblePromise;const entry=full.books[id-1];if(!entry)throw Error('Bible book not found');const book={};entry.chapters.forEach((verses,i)=>{book[i+1]=Object.fromEntries(verses.map(([v,text])=>[String(v),text]));});bookCache.set(id,book);return book;}
function textFor(ref){if(DATA.verses[ref])return DATA.verses[ref];const p=parseReference(ref);if(p&&p.verse&&bookCache.has(p.book.id))return bookCache.get(p.book.id)[p.ch]?.[p.verse]??'';return saved[ref]?.text??'';}
function readerPage(bookId,ch,verse,book){const b=DATA.index.find(x=>x.id===bookId);if(!b||!book[ch])return notFound('That chapter could not be found.');const verses=book[ch];activeReader={bookId,ch,verse};const invalidVerse=verse&&!verses[verse];const prev=ch>1?`#/read/${bookId}/${ch-1}`:bookId>1?`#/read/${bookId-1}/${DATA.index[bookId-2].chapters}`:null;const next=ch<b.chapters?`#/read/${bookId}/${ch+1}`:bookId<66?`#/read/${bookId+1}/1`:null;return `<div class="container"><header class="page-head"><span class="eyebrow">The complete Berean Standard Bible</span><h1>A little room for the Word.</h1><p>Choose a book and chapter. Tap a verse to save it or add a reflection.</p></header><div class="reader-toolbar"><label>Book<select id="reader-book" class="book-select" aria-label="Bible book">${DATA.index.map(x=>`<option value="${x.id}" ${x.id===bookId?'selected':''}>${x.name==='Psalm'?'Psalms':x.name}</option>`).join('')}</select></label><label>Chapter<select id="reader-chapter" aria-label="Chapter">${Array.from({length:b.chapters},(_,i)=>`<option value="${i+1}" ${ch===i+1?'selected':''}>${i+1}</option>`).join('')}</select></label><div class="reader-tools"><button class="btn outline" data-action="listen-chapter">${icon('volume')} Listen</button><button class="btn outline" data-action="text-size" aria-pressed="${largeText}">Aa <span>Text size</span></button></div></div><div class="reading ${largeText?'read-size-large':''}"><h2>${b.name} ${ch}</h2><p class="reader-description">BEREAN STANDARD BIBLE · ${Object.keys(verses).length} VERSES${bookId===19?` · <a class="source-link" href="#/psalms/${ch}${verse?'/'+verse:''}">ILLUSTRATED CHAPTER ↗</a>`:''}${bookId===19&&([23,46].includes(ch)||window.SFL_VERSE_STUDIES.has(ch))?` · <a class="source-link" href="#/study/${ch}/1">OPEN DETAILED STUDY ↗</a>`:''}</p>${invalidVerse?`<p class="choice-note" role="status">Verse ${verse} is not in this chapter. The complete chapter is shown below.</p>`:''}${Object.entries(verses).map(([v,text])=>{const ref=`${b.name} ${ch}:${v}`;return `<div class="reader-verse ${+v===verse?'selected':''}" id="verse-${v}" data-action="open-verse" data-ref="${escapeHTML(ref)}" data-speakref="${escapeHTML(ref)}"><span class="verse-number">${v}</span><span class="verse-body">${escapeHTML(text)}</span><button class="icon-btn" data-action="open-verse" data-ref="${escapeHTML(ref)}" aria-label="Save or reflect on ${escapeHTML(ref)}">${icon('bookmark')}</button></div>`;}).join('')}<div class="reader-pager">${prev?`<a class="btn outline" href="${prev}">${icon('back')} Previous chapter</a>`:'<span></span>'}${next?`<a class="btn outline" href="${next}">Next chapter ${icon('arrow')}</a>`:'<span></span>'}</div><p class="small">Text from the <a class="source-link" href="https://berean.bible/downloads.htm" target="_blank" rel="noopener noreferrer">official BSB download</a>. Psalm headings are included in the first verse where supplied by that source.</p></div></div>`;}
function storiesPage(){return `<div class="container"><header class="page-head"><span class="eyebrow">Stories of the Bible</span><h1>Follow the stories, book by book.</h1><p>Read the story episodes for Genesis, Exodus, Leviticus, Numbers, Deuteronomy, Joshua, Judges, and Ruth, 1 Samuel, 2 Samuel, 1 Kings, 2 Kings, Jonah, Amos, Hosea, Isaiah, Micah, Zephaniah, Obadiah, Lamentations, Ezekiel, Daniel, Haggai, Zechariah, Joel, Malachi, and now Chronicles, 332 episodes in all, with Scripture links and moments to reflect.</p></header><section class='gen-cta'><span class='gen-kicker'>THE STORY LIBRARY</span><h2>Choose a book.</h2><div class='gen-cta-actions'><a class='btn' href='#/stories'>Genesis stories →</a><a class='btn outline' href='#/exodus'>Exodus stories →</a><a class='btn outline' href='#/leviticus'>Leviticus stories →</a><a class='btn outline' href='#/numbers'>Numbers stories →</a><a class='btn outline' href='#/deuteronomy'>Deuteronomy stories →</a><a class='btn outline' href='#/joshua'>Joshua stories →</a><a class='btn outline' href='#/judges'>Judges stories →</a><a class='btn outline' href='#/ruth'>Ruth stories →</a><a class='btn outline' href='#/samuel1'>1 Samuel stories →</a><a class='btn outline' href='#/samuel2'>2 Samuel stories →</a><a class='btn outline' href='#/kings1'>1 Kings stories →</a><a class='btn outline' href='#/kings2'>2 Kings stories →</a><a class='btn outline' href='#/jonah'>Jonah stories →</a><a class='btn outline' href='#/amos'>Amos stories →</a><a class='btn outline' href='#/hosea'>Hosea stories →</a><a class='btn outline' href='#/isaiah'>Isaiah stories →</a><a class='btn outline' href='#/micah'>Micah stories →</a><a class='btn outline' href='#/nahum'>Nahum stories →</a><a class='btn outline' href='#/zephaniah'>Zephaniah stories →</a><a class='btn outline' href='#/jeremiah'>Jeremiah stories →</a><a class='btn outline' href='#/habakkuk'>Habakkuk stories →</a><a class='btn outline' href='#/obadiah'>Obadiah stories →</a><a class='btn outline' href='#/lamentations'>Lamentations stories →</a><a class='btn outline' href='#/ezekiel'>Ezekiel stories →</a><a class='btn outline' href='#/daniel'>Daniel stories →</a><a class='btn outline' href='#/haggai'>Haggai stories →</a><a class='btn outline' href='#/zechariah'>Zechariah stories →</a><a class='btn outline' href='#/joel'>Joel stories →</a><a class='btn outline' href='#/malachi'>Malachi stories →</a><a class='btn outline' href='#/chronicles'>Chronicles stories →</a><a class='btn outline' href='#/journey'>Journey through 66 books</a></div></section><p class="choice-note">Each story is a faithful retelling of the Berean Standard Bible, with the passage alongside it and a moment to reflect.</p></div>`;}
function peoplePage(){return `<div class="container people-page"><header class="page-head"><span class="eyebrow">Explore the people of the Bible</span><h1>Get to know their stories.</h1><p>Follow the passages behind the names. Explore their relationships, difficult choices, and the moments that shaped their stories.</p></header><div class="people-grid">${PEOPLE.map(personCard).join('')}</div><p class="choice-note">Explore these Bible character profiles. Every Bible book is available in the reader.</p></div>`;}
function personPage(id){const p=PEOPLE.find(x=>x.id===id);if(!p)return notFound();return `<div class="container"><header class="person-header"><div><a href="#/people" class="back">${icon('back')} People</a><span class="eyebrow">${p.tag}</span><h1>${p.name==='jesus'?'Jesus':p.name}</h1><p>${p.intro}</p></div><div class="person-visual">${scene(id==='peter'?2:1,'person')}<div class="person-symbol">${icon(p.icon)}</div><span class="scene-label">SYMBOLIC ART · NOT A PORTRAIT OR HISTORICAL RECONSTRUCTION</span></div></header>${window.SFL_CONNECTIONS.related({personId:id})}<div class="story-layout"><section class="timeline" aria-label="${p.name}'s story in sequence">${p.steps.map(([title,body,ref],i)=>`<article class="story-step"><span aria-hidden="true">0${i+1}</span><h3>${title}</h3><p>${body}</p><a class="text-link" href="${refURL(ref)}">Read the account · ${ref.replace(/:\d+$/,'')} ${icon('arrow')}</a></article>`).join('')}</section><aside class="side-note"><span class="eyebrow">Take the story with you</span><h3>A moment to reflect.</h3><p>${p.reflection}</p><a class="btn outline" href="#/help/${p.relatedTopic}">Find related encouragement ${icon('arrow')}</a>${id==='david'?'<a class="btn" href="#/study/23/1">Walk through Psalm 23</a>':''}${p.psalm46?'<a class="btn" href="#/study/46/1">Find refuge in Psalm 46</a>':''}${p.storyRoute?`<a class="btn outline" href="${p.storyRoute}">Read ${escapeHTML(p.storyLabel)} ${icon('arrow')}</a>`:''}<p class="small">These are original summaries of the referenced biblical accounts. Follow the links to read their full context. Interpretive comments are identified as such.</p></aside></div></div>`;}
function savedPage(storyNotes=[]){const entries=validSavedEntries();return `<div class="container"><header class="page-head"><span class="eyebrow">Words to return to</span><h1>Your quiet collection.</h1><p>Saved passages and reflections, kept in this browser on this device.</p></header>${!entries.length?`<section class="empty">${icon('bookmark')}<h2>Keep a verse close.</h2><p>When a passage speaks to you, tap its bookmark. Your saved verses and personal reflections will appear here.</p><a class="btn" href="#/">Find a passage ${icon('arrow')}</a></section>`:`<section class="saved-list">${entries.map(([ref,value])=>`<article class="verse-card"><div class="verse-heading"><a class="verse-ref" href="${refURL(ref)}">${escapeHTML(ref)} <span class="translation">BSB</span></a>${saveButton(ref)}</div><p class="verse-text">${escapeHTML(value.text)}</p>${notes[ref]?`<div class="saved-note"><span class="personal-label">YOUR REFLECTION</span><br>${escapeHTML(notes[ref])}</div>`:''}<div class="saved-actions">${studyLink(ref)?`<a class="text-link" href="${studyLink(ref)}">Understand this verse</a>`:''}<button class="text-link" data-action="open-verse" data-ref="${escapeHTML(ref)}">${notes[ref]?'Edit':'Add'} reflection</button><button class="text-link" data-action="copy-verse" data-ref="${escapeHTML(ref)}">Copy verse</button>${shareButton(ref,'text-link','Share')}</div></article>`).join('')}</section>`}${storyReflectionsSection(storyNotes)}</div>`;}
const STORY_NOTE_KEY=/^scripture-for-life\.([a-z0-9]+)-note-([^-]+)-(\d+)$/;
const storyDataCache=new Map();
function storyBookName(slug){const m=slug.match(/^([a-z]+?)([12])$/);return m?`${m[2]} ${m[1][0].toUpperCase()}${m[1].slice(1)}`:slug[0].toUpperCase()+slug.slice(1);}
function storyBookOrder(name){const b=DATA.index.find(x=>x.name===name);return b?b.id:999;}
function loadStoryData(slug){if(!storyDataCache.has(slug)){const files=slug==='genesis'?['data/episodes.json','data/story-scenes.json']:[`data/${slug}-episodes.json`,`data/${slug}-scenes.json`];storyDataCache.set(slug,Promise.all(files.map(f=>fetch(f).then(r=>{if(!r.ok)throw Error('Story content unavailable');return r.json();}))).then(([episodes,scenes])=>({episodes,scenes})).catch(()=>{storyDataCache.delete(slug);return null;}));}return storyDataCache.get(slug);}
function storyNoteEntries(){const out=[];try{for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i),m=key&&key.match(STORY_NOTE_KEY);if(!m)continue;const text=localStorage.getItem(key)||'';if(!text.trim())continue;out.push({slug:m[1],episode:m[2],scene:+m[3],text});}}catch{}return out;}
async function storyReflections(){const entries=storyNoteEntries();if(!entries.length)return [];const books=[...new Set(entries.map(e=>e.slug))];const data=Object.fromEntries(await Promise.all(books.map(async slug=>[slug,await loadStoryData(slug)])));return entries.map(e=>{const d=data[e.slug],ep=Array.isArray(d?.episodes)?d.episodes.find(x=>String(x.id)===e.episode):null,sc=d?.scenes?.[e.episode]?.[e.scene-1],book=storyBookName(e.slug);return {...e,book,order:storyBookOrder(book),episodeTitle:ep?.title||'',sceneTitle:sc?.title||'',href:`#/${e.slug==='genesis'?'stories':e.slug}/${e.episode}/${e.scene}`};}).sort((a,b)=>a.order-b.order||(+a.episode||0)-(+b.episode||0)||a.scene-b.scene);}
function storyReflectionsSection(list){if(!list?.length)return '';return `<section class="story-reflections" aria-labelledby="story-reflections-title"><div class="section-heading"><div><h2 id="story-reflections-title">Your story reflections</h2><p>Thoughts you saved while reading the stories.</p></div></div>${list.map(r=>`<article class="verse-card story-reflection"><div class="verse-heading"><a class="verse-ref" href="${escapeHTML(r.href)}">${escapeHTML(r.book)} · Episode ${escapeHTML(r.episode)}${r.episodeTitle?`: ${escapeHTML(r.episodeTitle)}`:''} · Scene ${r.scene}</a></div>${r.sceneTitle?`<p class="verse-text">${escapeHTML(r.sceneTitle)}</p>`:''}<div class="saved-note"><span class="personal-label">YOUR REFLECTION</span><br>${escapeHTML(r.text)}</div><div class="saved-actions"><a class="text-link" href="${escapeHTML(r.href)}">Open this scene</a></div></article>`).join('')}</section>`;}
function searchBody(query){const results=searchTopics(query),parsed=parseReference(query);return `${parsed?`<section class="side-note" style="position:static;margin-bottom:25px"><h3>${escapeHTML(parsed.book.name)} ${parsed.ch}${parsed.verse?':'+parsed.verse:''}</h3><p>Open this passage in the Berean Standard Bible.</p><a class="btn" style="width:auto" href="${refURL(query)}">Read passage ${icon('arrow')}</a></section>`:''}${results.length?`<p class="search-summary">${results.length} related ${results.length===1?'topic':'topics'} for “${escapeHTML(query)}”</p><div class="topic-grid" style="margin-top:20px">${results.map(topicCard).join('')}</div>`:parsed?`<p class="search-summary">Explore a topic alongside your reading.</p><div class="topic-grid" style="margin-top:20px">${DATA.topics.map(topicCard).join('')}</div>`:''}<div id="word-results" class="word-results" aria-live="polite"></div>`;}
function searchPage(query){return `<div class="container search-results"><header class="page-head"><a class="back" href="#/">${icon('back')} Find help</a><span class="eyebrow">Find a place to begin</span><h1>Words for what you’re carrying.</h1>${searchForm(query)}</header><div id="search-body">${searchBody(query)}</div></div>`;}
/* Word search: Bible verses (bundled BSB), story scenes and people. Indexes build lazily on first search and stay offline. */
const WS={bible:null,stories:null,last:null,shown:{verses:50,stories:20}};let wordToken=0,wordTimer=null,pendingWordSearch=null;
function wsWords(q){return String(q).replace(/[\u201C\u201D"\u00AB\u00BB]/g,' ').replace(/[\u2018\u2019]/g,"'").replace(/[^\p{L}\p{N}'\s-]/gu,' ').toLowerCase().split(/\s+/).map(w=>w.replace(/^['-]+|['-]+$/g,'')).filter(Boolean).slice(0,12);}
function wsPart(w){return w.replace(/[.*+?^${}()|[\]\\]/g,'\\$&').replace(/'/g,"['\u2019]").replace(/-/g,'[-\u2013\u2014]?');}
function wsMatcher(q){const words=wsWords(q);if(!words.length||words.join('').replace(/[^\p{L}\p{N}]/gu,'').length<2)return null;const start='(?<![\\p{L}\\p{N}])';const phrase=new RegExp(start+words.map(wsPart).join('[^\\p{L}\\p{N}]+'),'iu');const each=words.map(w=>new RegExp(start+wsPart(w),'iu'));return {words,phrase,each,highlight:new RegExp(start+'(?:'+[words.map(wsPart).join('[^\\p{L}\\p{N}]+'),...(words.length>1?words.map(wsPart):[])].join('|')+')','giu')};}
function wsHighlight(text,m){let out='',at=0;for(const hit of text.matchAll(m.highlight)){out+=escapeHTML(text.slice(at,hit.index))+'<mark>'+escapeHTML(hit[0])+'</mark>';at=hit.index+hit[0].length;}return out+escapeHTML(text.slice(at));}
function wsSnippet(text,m,re){const hit=re.exec(text);if(!hit)return wsHighlight(text.slice(0,180),m)+(text.length>180?'…':'');const a=Math.max(0,hit.index-80),b=Math.min(text.length,hit.index+hit[0].length+120);let s=text.slice(a,b);if(a>0)s=s.replace(/^\S*\s/,'');if(b<text.length)s=s.replace(/\s\S*$/,'');return (a>0?'…':'')+wsHighlight(s,m)+(b<text.length?'…':'');}
function wsBible(){if(!WS.bible)WS.bible=loadBook(1).then(()=>sharedBiblePromise).then(full=>{const list=[];full.books.forEach((b,bi)=>{const info=DATA.index[bi];if(!info)return;b.chapters.forEach((vs,ci)=>vs.forEach(([v,t])=>list.push({ref:`${info.name} ${ci+1}:${v}`,url:`#/read/${info.id}/${ci+1}/${v}`,text:t})));});return list;}).catch(e=>{WS.bible=null;throw e;});return WS.bible;}
function wsStoryBooks(){const html=storiesPage(),i=html.indexOf('gen-cta-actions'),list=i<0?html:html.slice(i,html.indexOf('</div>',i));return [...new Set([...list.matchAll(/href='#\/([a-z0-9]+)'/g)].map(m=>m[1]==='stories'?'genesis':m[1]).filter(x=>!['journey','books','people'].includes(x)))];}
function wsStories(){let failed=false;if(!WS.stories)WS.stories=Promise.all(wsStoryBooks().map(async slug=>{const d=await loadStoryData(slug);if(!d||!Array.isArray(d.episodes)){failed=true;return [];}const book=storyBookName(slug),route=slug==='genesis'?'stories':slug;return d.episodes.flatMap(ep=>(d.scenes?.[ep.id]||[]).map((sc,i)=>({book,order:storyBookOrder(book),episode:String(ep.id),epTitle:ep.title||'',scene:i+1,title:sc.title||'',text:(ep.paragraphs||[]).slice(sc.start,sc.end+1).join(' '),href:`#/${route}/${ep.id}/${i+1}`})));})).then(a=>{if(failed)WS.stories=null;return a.flat().sort((x,y)=>x.order-y.order);}).catch(()=>{WS.stories=null;return [];});return WS.stories;}
async function wordSearch(q){const m=wsMatcher(q);if(!m)return null;const t0=performance.now();const [bible,stories]=await Promise.all([wsBible(),wsStories()]);const tLoad=performance.now();
 let verses=[];for(let i=0;i<bible.length;i+=4000){const end=Math.min(bible.length,i+4000);for(let j=i;j<end;j++)if(m.phrase.test(bible[j].text))verses.push(bible[j]);if(end<bible.length)await new Promise(r=>setTimeout(r,0));}
 const exact=new RegExp(m.phrase.source+'(?![\\p{L}\\p{N}])','iu');verses=verses.map((v,i)=>[exact.test(v.text)?0:1,i,v]).sort((a,b)=>a[0]-b[0]||a[1]-b[1]).map(x=>x[2]);let allWords=false;if(!verses.length&&m.words.length>1){allWords=true;verses=bible.filter(v=>m.each.every(re=>re.test(v.text)));}
 const sceneHits=stories.filter(s=>m.phrase.test(s.title)||m.phrase.test(s.text));
 const people=PEOPLE.filter(p=>m.phrase.test(p.name)||m.phrase.test(p.tag||''));
 return {q,m,verses,allWords,stories:sceneHits,people,ms:Math.round(performance.now()-tLoad),loadMs:Math.round(tLoad-t0)};}
function wsShowQuery(q){return String(q).trim().replace(/^[\s"\u201C\u201D'\u2018\u2019]+|[\s"\u201C\u201D'\u2018\u2019]+$/g,'');}
function wordResultsHTML(r){const q=escapeHTML(wsShowQuery(r.q));const parts=[];
 if(r.verses.length){const shown=r.verses.slice(0,WS.shown.verses);parts.push(`<section class="word-section" aria-labelledby="word-verses-title"><div class="section-heading"><div><h2 id="word-verses-title">Bible verses</h2><p class="word-count">${r.verses.length.toLocaleString()} ${r.verses.length===1?'verse':'verses'} ${r.allWords?'contain all of these words':'contain'} “${q}”${r.verses.length>shown.length?`, showing ${shown.length}`:''}</p></div></div>${shown.map(v=>`<article class="verse-card word-hit"><div class="verse-heading"><a class="verse-ref" href="${v.url}">${escapeHTML(v.ref)} <span class="translation">BSB</span></a></div><p class="verse-text">${wsHighlight(v.text,r.m)}</p><div class="verse-actions"><a class="text-link" href="${v.url}">Read in context</a></div></article>`).join('')}${r.verses.length>shown.length?`<p><button class="btn outline" data-action="word-more" data-kind="verses">Show more verses (${(r.verses.length-shown.length).toLocaleString()} more)</button></p>`:''}</section>`);}
 if(r.stories.length){const shown=r.stories.slice(0,WS.shown.stories);parts.push(`<section class="word-section" aria-labelledby="word-stories-title"><div class="section-heading"><div><h2 id="word-stories-title">Story scenes</h2><p class="word-count">${r.stories.length} ${r.stories.length===1?'scene':'scenes'} mention “${q}”${r.stories.length>shown.length?`, showing ${shown.length}`:''}</p></div></div>${shown.map(s=>`<article class="verse-card word-hit word-story"><div class="verse-heading"><a class="verse-ref" href="${s.href}">${escapeHTML(s.book)} · Episode ${escapeHTML(s.episode)}${s.epTitle?`: ${escapeHTML(s.epTitle)}`:''} · Scene ${s.scene}</a></div><p class="verse-text"><a href="${s.href}">${wsHighlight(s.title,r.m)}</a></p><p class="small">${wsSnippet(s.text,r.m,r.m.phrase)}</p></article>`).join('')}${r.stories.length>shown.length?`<p><button class="btn outline" data-action="word-more" data-kind="stories">Show more scenes (${r.stories.length-shown.length} more)</button></p>`:''}</section>`);}
 if(r.people.length)parts.push(`<section class="word-section" aria-labelledby="word-people-title"><div class="section-heading"><div><h2 id="word-people-title">People</h2><p class="word-count">${r.people.length} ${r.people.length===1?'person':'people'} for “${q}”</p></div></div><div class="people-grid">${r.people.map(personCard).join('')}</div></section>`);
 return parts.join('');}
function wordEmptyHTML(q,hasOther){return hasOther?`<p class="search-summary">No Bible verses, stories or people mention “${escapeHTML(wsShowQuery(q))}”.</p>`:`<div class="no-results"><h2>You can start where you are.</h2><p>We couldn’t find “${escapeHTML(wsShowQuery(q))}” in the Bible text, the stories, or the people. Check the spelling, try a single word such as “shepherd,” a feeling such as “fear” or “grief,” or a reference such as “Psalm 23:4.”</p></div><div class="topic-grid" style="margin-top:20px">${DATA.topics.map(topicCard).join('')}</div>`;}
async function runWordSearch(q){const token=++wordToken;const box=$('#word-results');if(!box)return;const hasOther=!!(parseReference(q)||searchTopics(q).length);if(parseReference(q)){box.innerHTML='';return;}
 WS.shown={verses:50,stories:20};box.setAttribute('aria-busy','true');box.innerHTML='<p class="loading" role="status">Searching the Bible, stories and people…</p>';
 let r;try{r=await wordSearch(q);}catch{if(token===wordToken){box.removeAttribute('aria-busy');box.innerHTML='<p class="search-summary">The Bible text could not be loaded for word search. Please try again.</p>';}return;}
 if(token!==wordToken||!document.body.contains(box))return;WS.last=r;window.SFL_LAST_SEARCH_MS=r?r.ms:0;window.SFL_LAST_SEARCH_LOAD_MS=r?r.loadMs:0;box.removeAttribute('aria-busy');
 box.innerHTML=r&&(r.verses.length||r.stories.length||r.people.length)?wordResultsHTML(r):wordEmptyHTML(q,hasOther);}
function aboutPage(){return `<article class="about"><a class="back" href="#/">${icon('back')} Find help</a><span class="eyebrow">Our approach & sources</span><h1>Scripture at the center.</h1><p>Scripture for Life is a place to find encouragement in God’s Word, read in context, and explore the people and stories of the Bible.</p><h2>The Bible text</h2><p>This site uses the complete 66-book Berean Standard Bible (BSB), downloaded from the publisher’s <a href="https://berean.bible/downloads.htm" target="_blank" rel="noopener noreferrer">official downloads page</a>. The text has been dedicated to the public domain. <a href="https://berean.bible/terms.htm" target="_blank" rel="noopener noreferrer">Read the publisher’s terms.</a></p><p>The Holy Bible, Berean Standard Bible, BSB is produced in cooperation with Bible Hub, Discovery Bible, unfoldingWord, Bible Aquifer, OpenBible.com, and the Berean Bible Translation Committee. This text of God’s Word has been dedicated to the public domain.</p><p>Source retrieved October 18, 2026. All 31,102 source verse rows are preserved verbatim. Verse headings are retained when included in the publisher’s text file. <a href="bible/source.json" target="_blank">View source provenance.</a></p><h2>Understanding a passage</h2><ul><li><strong>Scripture:</strong> the quoted BSB text, with its exact reference.</li><li><strong>Explanation:</strong> original editorial notes, distinguished from Scripture.</li><li><strong>Context:</strong> the surrounding account, the kind of writing, and relevant translation notes.</li><li><strong>Application:</strong> questions to help readers reflect, without claiming a personal message from God on their behalf.</li></ul><p>Where interpretations differ, the study should acknowledge that difference and point to the relevant text. Original-language notes require a cited source; this sample uses the BSB translation footnotes instead of presenting unsupported Hebrew or Greek claims.</p><p>The illustrated studies reference <a href="https://biblehub.com/bsb/psalms/23.htm" target="_blank" rel="noopener noreferrer">Psalm 23</a> and <a href="https://biblehub.com/bsb/psalms/46.htm" target="_blank" rel="noopener noreferrer">Psalm 46</a>, including the BSB translation footnotes. People profiles link directly to the passages they summarize. No third-party commentary has been copied into this site.</p><h2>What’s included in this first edition</h2><p>The full BSB reader, eight curated help topics, a six-part Psalm 23 study, and introductory Bible character profiles for Jesus, David, Ruth, Peter, and Esther. All 150 Psalms have illustrated chapter pages with complete BSB text, concise editorial introductions, context, reading prompts, and optional reflections. Completed verse-by-verse studies appear in the Psalms collection alongside the full chapter pages, with a detailed section study for Psalm 46. Psalm 46 covers all eleven verses across six sections and links to profiles of Jacob and the sons of Korah. The same original warm visual theme is used throughout the Psalms.</p><h2>Illustration & narration</h2><p>The landscape illustrations are original symbolic artwork inspired by the psalm. They are not photographs, portraits, or reconstructions of a known historical location. Listening uses your device’s available text-to-speech voice. Availability and pronunciation vary by device; some voices may use the device provider’s online speech service.</p><h2>Your notes belong to you</h2><p>Bookmarks and reflections are stored in this browser’s local storage. This app does not send them to a server. They do not automatically sync between devices, and clearing browser storage removes them. Other people using this browser can access them. No account is required by the app.</p><h2>Care when life is difficult</h2><p class="notice">The health and illness readings offer spiritual encouragement, prayer, and context. They do not diagnose a condition, guarantee healing, or replace medical care. Seeking help from trusted people and qualified professionals can be part of caring for yourself.</p></article>`;}
