function episodeChunks(paragraphs,max=220){const out=[];paragraphs.forEach((text,p)=>{const parts=String(text).replace(/\s+/g,' ').trim().match(/[^.!?;:]+[.!?;:]+[”’"')\]]*\s*|[^.!?;:]+$/g)||[];let buf='';const push=()=>{if(buf.trim())out.push({p,text:buf.trim()});buf='';};parts.forEach(s=>{if(s.length>max){push();s.split(/(?<=,)\s+|\s+(?=—)/).flatMap(w=>w.length>max?w.split(' '):[w]).forEach(w=>{if((buf+' '+w).length>max)push();buf+=(buf?' ':'')+w;});push();return;}if((buf+s).length>max)push();buf+=s;});push();});return out;}
function episodeListenControls(){return `<div class="gen-reading-controls ep-listen"><button class="btn outline" data-action="ep-listen">▶ Listen to the whole episode</button><button class="btn outline" data-action="ep-pause" hidden aria-pressed="false">Pause</button><button class="btn outline" data-action="ep-stop" hidden>Stop narration</button><label>Speed <select id="ep-speed"><option value=".8">0.8×</option><option value="1" selected>1×</option><option value="1.15">1.15×</option></select></label></div>`;}
function mountEpisodeListen(){const full=$('#main .gen-full');if(!full||full.querySelector('.ep-listen'))return;const narrative=full.querySelector('.gen-narrative');if(narrative)narrative.insertAdjacentHTML('beforebegin',episodeListenControls());}
function resetEpisodeListen(){document.querySelectorAll('.ep-listen').forEach(box=>{box.querySelector('[data-action="ep-listen"]').hidden=false;const pause=box.querySelector('[data-action="ep-pause"]');pause.hidden=true;pause.textContent='Pause';pause.setAttribute('aria-pressed','false');box.querySelector('[data-action="ep-stop"]').hidden=true;});document.querySelectorAll('.gen-full .gen-speaking').forEach(p=>p.classList.remove('gen-speaking'));}
function listenEpisode(){stopAudio();if(!('speechSynthesis'in window)||!('SpeechSynthesisUtterance'in window)){notify('Narration is not available in this browser. The full text is here to read.');return;}const nodes=[...document.querySelectorAll('#main .gen-full .gen-narrative p')],chunks=episodeChunks(nodes.map(p=>p.textContent));if(!chunks.length)return;try{speechSynthesis.resume();}catch{}const generation=audioGeneration,rate=Number($('#ep-speed')?.value||1),box=$('.ep-listen');box.querySelector('[data-action="ep-listen"]').hidden=true;box.querySelector('[data-action="ep-pause"]').hidden=false;box.querySelector('[data-action="ep-stop"]').hidden=false;let at=0;
 function next(){if(generation!==audioGeneration)return;if(at>=chunks.length){stopAudio();return;}const c=chunks[at++];nodes.forEach((p,i)=>p.classList.toggle('gen-speaking',i===c.p));if(at===1||chunks[at-2].p!==c.p)nodes[c.p].scrollIntoView({block:'nearest',behavior:'smooth'});const utter=new SpeechSynthesisUtterance(c.text);utter.lang='en-US';utter.rate=rate;const voice=speechSynthesis.getVoices().find(v=>v.lang==='en-US'&&v.localService)||speechSynthesis.getVoices().find(v=>v.lang.startsWith('en'));if(voice)utter.voice=voice;utter.onend=next;utter.onerror=e=>{if(generation!==audioGeneration||e.error==='canceled'||e.error==='interrupted')return;stopAudio();notify('Your device could not start narration. Please try another available voice or browser.');};speechSynthesis.speak(utter);}
 next();}
function pauseEpisode(btn){if(!('speechSynthesis'in window))return;const paused=btn.getAttribute('aria-pressed')==='true';if(paused)speechSynthesis.resume();else speechSynthesis.pause();btn.setAttribute('aria-pressed',String(!paused));btn.textContent=paused?'Pause':'Resume';}
function stopAudio(){audioGeneration++;if('speechSynthesis'in window)window.speechSynthesis.cancel();$('#audio-bar').hidden=true;document.querySelectorAll('.speaking').forEach(e=>e.classList.remove('speaking'));resetEpisodeListen();}
function speakRefs(refs){stopAudio();if(!('speechSynthesis'in window)||!('SpeechSynthesisUtterance'in window)){notify('Narration is not available in this browser. The full text is here to read.');return;}const generation=audioGeneration;let at=0;const queue=refs.filter(r=>textFor(r));if(!queue.length){notify('This passage is not available to read aloud yet.');return;}
 function next(){if(generation!==audioGeneration)return;if(at>=queue.length){stopAudio();return;}const ref=queue[at++],utter=new SpeechSynthesisUtterance(textFor(ref));utter.lang='en-US';utter.rate=.88;const voice=speechSynthesis.getVoices().find(v=>v.lang==='en-US'&&v.localService)||speechSynthesis.getVoices().find(v=>v.lang.startsWith('en'));if(voice)utter.voice=voice;$('#audio-bar').hidden=false;$('#audio-status').textContent=`Listening · ${ref} · BSB`;document.querySelectorAll('[data-speakref]').forEach(e=>e.classList.toggle('speaking',e.dataset.speakref===ref));utter.onend=next;utter.onerror=(e)=>{if(generation!==audioGeneration||e.error==='canceled'||e.error==='interrupted')return;stopAudio();notify('Your device could not start narration. Please try another available voice or browser.');};speechSynthesis.speak(utter);}
 next();
}
const SITE_URL='https://dvdjoe-sudo.github.io/scripture-for-life/';
function shareBase(){return location.protocol==='https:'&&location.hostname!=='localhost'?location.origin+location.pathname:SITE_URL;}
function nativeShare(){const cap=window.Capacitor;if(!cap||typeof cap.isNativePlatform!=='function'||!cap.isNativePlatform())return null;const plugin=cap.Plugins&&cap.Plugins.Share;return plugin&&typeof plugin.share==='function'?plugin:null;}
async function shareContent(title,text,hash){const url=shareBase()+hash,full=`${text}\n\n${url}`;const native=nativeShare();if(native){try{await native.share({title,text,url,dialogTitle:'Share'});return 'shared';}catch(e){if(/cancel/i.test(String(e&&(e.message||e.code)||'')))return 'cancelled';}}if(typeof navigator.share==='function'){try{await navigator.share({title,text,url});return 'shared';}catch(e){if(e&&e.name==='AbortError')return 'cancelled';}}try{await navigator.clipboard.writeText(full);notify('Copied');return 'copied';}catch{const dialog=$('#verse-dialog');$('#dialog-content').innerHTML='<h2 id="dialog-title">Copy to share</h2><p class="small">Select and copy the text below.</p><textarea id="copy-passage" class="note-input" readonly></textarea>';$('#copy-passage').value=full;if(!dialog.open)dialog.showModal();$('#copy-passage').select();return 'manual';}}
function shareVerse(ref){const text=textFor(ref);if(!text)return;return shareContent(`${ref} (BSB)`,`“${text}”\n— ${ref}, Berean Standard Bible (BSB)`,studyLink(ref)||refURL(ref));}
function shareScene(){const main=$('#main'),h=location.hash.split('/').filter(Boolean),title=main.querySelector('.gen-content h1')?.textContent.trim()||'',passage=(main.querySelector('.gen-passage')?.textContent||'').replace(/\s*·\s*BSB\s*$/,'').trim(),slug=h[1]==='stories'?'genesis':h[1];return shareContent(title,`${title} — ${storyBookName(slug)} story, Episode ${h[2]} · Scene ${h[3]}\n${passage} (BSB)`,`#/${h[1]}/${h[2]}/${h[3]}`);}
const shareButton=(ref,cls='icon-btn',label='Share')=>`<button class="${cls}" data-action="share-verse" data-ref="${escapeHTML(ref)}">${cls==='icon-btn'?icon('share')+' ':''}${label}</button>`;
function addStoryTextSize(){const rows=[...document.querySelectorAll('#main .gen-content .gen-reading-controls')];rows.forEach(row=>{if(!row.querySelector('[data-action="text-size"]'))row.insertAdjacentHTML('beforeend',`<button class="btn outline" data-action="text-size" aria-pressed="${largeText}">Aa <span>Text size</span></button>`);});}
function addShareButtons(parts){const main=$('#main');if(parts[0]==='study'||parts[0]==='psalms')main.querySelectorAll('.verse-actions [data-action="copy-verse"]').forEach(b=>{if(!b.parentElement.querySelector('[data-action="share-verse"]'))b.insertAdjacentHTML('afterend',shareButton(b.dataset.ref));});if(parts.length===3&&/^\d+$/.test(parts[1])&&/^\d+$/.test(parts[2])&&main.querySelector('.gen-narrative')){const row=main.querySelector('.gen-reading-controls');if(row&&!row.querySelector('[data-action="share-scene"]'))row.insertAdjacentHTML('beforeend','<button class="btn outline" data-action="share-scene">Share<span class="wide-only"> this scene</span></button>');}}
function openVerse(ref){const text=textFor(ref);if(!text){notify('Open this passage in the reader first.');return;}const content=$('#dialog-content');content.className='dialog-content';content.innerHTML=`<span class="eyebrow">A verse to spend time with · BSB</span><h2 id="dialog-title">${escapeHTML(ref)}</h2><p class="verse-text">${escapeHTML(text)}</p><div class="verse-actions">${saveButton(ref,true)}<button class="icon-btn" data-action="copy-verse" data-ref="${escapeHTML(ref)}">${icon('copy')} Copy</button><button class="icon-btn" data-action="listen-verse" data-ref="${escapeHTML(ref)}">${icon('volume')} Listen</button>${shareButton(ref)}</div>${studyLink(ref)?`<p style="margin-top:15px"><a class="text-link" href="${studyLink(ref)}">Understand this verse in the verse study ↗</a></p>`:''}${noteField(ref)}<div class="verse-actions" style="margin-top:15px"><button class="btn" data-action="save-note" data-ref="${escapeHTML(ref)}">Save reflection</button><a class="text-link" href="${refURL(ref)}">Read in context</a></div>`;hydrateNotes();$('#verse-dialog').showModal();}
async function copyText(text){try{await navigator.clipboard.writeText(text);notify('Verse copied with its reference.');}catch{const dialog=$('#verse-dialog');$('#dialog-content').innerHTML='<h2 id="dialog-title">Copy this passage</h2><p class="small">Select and copy the text below.</p><textarea id="copy-passage" class="note-input" readonly></textarea>';$('#copy-passage').value=text;if(!dialog.open)dialog.showModal();$('#copy-passage').select();}}
document.addEventListener('click',async e=>{const anchor=e.target.closest('a[href]');if(anchor?.classList.contains('skip-link')){e.preventDefault();$('#main').focus();$('#main').scrollIntoView({block:'start'});return;}if(anchor?.closest('dialog')&&anchor.getAttribute('href').startsWith('#/'))$('#verse-dialog').close();const target=e.target.closest('[data-action]');if(!target)return;const action=target.dataset.action,ref=target.dataset.ref;e.preventDefault();
 if(action==='save'){const text=textFor(ref);if(!text)return;const next={...saved};if(next[ref])delete next[ref];else next[ref]={text};if(persist('scripture-for-life.saved',next)){saved=next;updateSavedUI();notify(saved[ref]?'Verse saved on this device.':'Verse removed from saved collection.');if(location.hash==='#/saved'&&!$('#verse-dialog').open)render();}}
 else if(action==='open-verse')openVerse(ref);
 else if(action==='close-dialog'){$('#verse-dialog').close();stopAudio();}
 else if(action==='listen-verse')speakRefs([ref]);
 else if(action==='listen-psalm-chapter'){const n=Number(target.dataset.chapter),book=bookCache.get(19);if(Number.isInteger(n)&&book?.[n])speakRefs(Object.keys(book[n]).map(v=>`Psalm ${n}:${v}`));}
 else if(action==='listen-psalm')speakRefs(Array.from({length:6},(_,i)=>`Psalm 23:${i+1}`));
 else if(action==='listen-psalm46')speakRefs(Array.from({length:11},(_,i)=>`Psalm 46:${i+1}`));
 else if(action==='listen-psalm46-section'){const n=Number(target.dataset.section);if(Number.isInteger(n)&&n>=1&&n<=6)speakRefs(window.SFL_PSALM46.refs(n));}
 else if(action==='word-more'){const kind=target.dataset.kind;if(WS.last&&(kind==='verses'||kind==='stories')){WS.shown[kind]+=kind==='verses'?50:20;const y=window.scrollY;$('#word-results').innerHTML=wordResultsHTML(WS.last);window.scrollTo({top:y,behavior:'instant'});}}
 else if(action==='stop-audio')stopAudio();
 else if(action==='ep-listen')listenEpisode();
 else if(action==='ep-pause')pauseEpisode(target);
 else if(action==='ep-stop')stopAudio();
 else if(action==='share-verse')await shareVerse(ref);
 else if(action==='share-scene')await shareScene();
 else if(action==='copy-verse')await copyText(`${textFor(ref)}\n\n${ref} — Berean Standard Bible (BSB)`);
 else if(action==='study-tab'){const n=+(location.hash.split('/')[3]||1);studyTab=target.dataset.tab;document.querySelectorAll('.tab').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.tab===studyTab));b.tabIndex=b.dataset.tab===studyTab?0:-1;});$('#study-panel').innerHTML=studyPanel(n);hydrateNotes();$('#study-panel').setAttribute('aria-labelledby',`tab-${studyTab}`);}
 else if(action==='save-note'){const root=target.closest('dialog')||target.closest('.study-explainer');const value=root?.querySelector('textarea')?.value??'';const next={...notes};if(value.trim())next[ref]=value;else delete next[ref];if(persist('scripture-for-life.notes',next)){notes=next;const nextSaved={...saved,[ref]:{text:textFor(ref)}};if(persist('scripture-for-life.saved',nextSaved)){saved=nextSaved;updateSavedUI();notify(value.trim()?'Reflection saved on this device.':'Reflection cleared; verse kept in your collection.');}}}
 else if(action==='listen-chapter'&&activeReader){const {bookId,ch}=activeReader;const book=bookCache.get(bookId);speakRefs(Object.keys(book[ch]).map(v=>`${DATA.index[bookId-1].name} ${ch}:${v}`));}
 else if(action==='text-size'){largeText=!largeText;try{localStorage.setItem(TEXT_SIZE_KEY,largeText?'large':'normal');}catch{}applyTextSize();notify(largeText?'Larger text is on across the app.':'Standard text size.');}
});
document.addEventListener('input',e=>{if(e.target.id!=='help-search'||!location.hash.startsWith('#/search')||!$('#search-body'))return;clearTimeout(wordTimer);wordTimer=setTimeout(()=>{const q=e.target.value.trim().slice(0,150);if(!q)return;history.replaceState(null,'',`#/search/${encodeURIComponent(q)}`);$('#search-body').innerHTML=searchBody(q);runWordSearch(q);},350);});
document.addEventListener('submit',e=>{if(e.target.dataset.form!=='search')return;e.preventDefault();const q=new FormData(e.target).get('query').trim().slice(0,150);if(q)location.hash=`#/search/${encodeURIComponent(q)}`;});
document.addEventListener('change',e=>{if(e.target.id==='reader-book')location.hash=`#/read/${e.target.value}/1`;if(e.target.id==='reader-chapter'&&activeReader)location.hash=`#/read/${activeReader.bookId}/${e.target.value}`;});
document.addEventListener('keydown',e=>{if(e.target.matches('[role="tab"]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=[...document.querySelectorAll('[role="tab"]')],i=tabs.indexOf(e.target),next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].focus();tabs[next].click();}});
$('#verse-dialog').addEventListener('close',()=>{stopAudio();if(location.hash==='#/saved')render();});
window.addEventListener('hashchange',render);
window.addEventListener('pagehide',stopAudio);
window.APP_TEST={shareContent,shareBase,heroVerse,dailyVersePool,episodeChunks,lastPlace,timeAgo,parseReference,searchTopics,refURL,escapeHTML,home,helpPage,studyPage,studyPanel,readerPage,peoplePage,personPage,savedPage,storyReflections,searchPage,wordSearch,aboutPage,textFor,loadBook};
render();
